"use client";

// Flat 2D dentition chart — a print-friendly schematic of the whole mouth with
// the upper teeth on one straight row and the lower teeth on another (instead
// of the 3D curved arch, which is WebGL and does not print). Reads the saved
// examination chart from localStorage so it can render inside the Rx preview /
// printed report without sharing the live DentalCanvas React state.

import { useEffect, useState } from "react";

const EXAM_CHART_PREFIX = "dental.exam.chart.";

// Permanent dentition, laid left→right as seen facing the patient.
const UPPER_ROW = ["18", "17", "16", "15", "14", "13", "12", "11", "21", "22", "23", "24", "25", "26", "27", "28"];
const LOWER_ROW = ["48", "47", "46", "45", "44", "43", "42", "41", "31", "32", "33", "34", "35", "36", "37", "38"];

const MISSING = new Set(["Missing", "Extraction"]);

function loadChart(patientId) {
  if (typeof window === "undefined") return null;
  try {
    const raw = window.localStorage.getItem(`${EXAM_CHART_PREFIX}${patientId || "apt-1"}`);
    if (!raw) return null;
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

// Geometry
const PAD = 10;
const TW = 26;        // tooth glyph width
const STEP = 30;      // horizontal step between teeth
const CENTER_GAP = 12; // extra gap between the two quadrants of a row
const GLYPH_H = 30;
const LABEL_H = 13;
const ROW_GAP = 16;
const ROW_LABEL_W = 0;

function xFor(i) {
  return PAD + i * STEP + (i >= 8 ? CENTER_GAP : 0);
}
const CHART_W = PAD * 2 + 16 * STEP + CENTER_GAP;

function toothState(fdi, toothDiagnoses, findingsByTooth) {
  const diags = toothDiagnoses?.[fdi] ?? [];
  const findings = (findingsByTooth?.[fdi] ?? []).filter((f) => f && f.type && f.type !== "Normal");
  const isMissing = diags.some((d) => MISSING.has(d));
  const treated = diags.length > 0 && !isMissing;
  return { diags, findingCount: findings.length, isMissing, treated, hasAny: diags.length > 0 || findings.length > 0 };
}

function Tooth({ fdi, x, y, st }) {
  const fill = st.isMissing ? "#e2e8f0" : st.treated ? "#ede9fe" : "#ffffff";
  const stroke = st.isMissing ? "#94a3b8" : st.treated ? "#7c3aed" : st.findingCount ? "#d97706" : "#cbd5e1";
  return (
    <g>
      {/* crown glyph: rounded-top rect */}
      <path
        d={`M${x + 3},${y + GLYPH_H} L${x + 3},${y + 8} Q${x + 3},${y} ${x + 8},${y} L${x + TW - 5},${y} Q${x + TW},${y} ${x + TW},${y + 8} L${x + TW},${y + GLYPH_H} Z`}
        fill={fill}
        stroke={stroke}
        strokeWidth={st.treated || st.isMissing ? 1.6 : 1.1}
      />
      {/* missing → diagonal cross */}
      {st.isMissing && (
        <>
          <line x1={x + 5} y1={y + 4} x2={x + TW - 2} y2={y + GLYPH_H - 3} stroke="#64748b" strokeWidth="1.4" />
          <line x1={x + TW - 2} y1={y + 4} x2={x + 5} y2={y + GLYPH_H - 3} stroke="#64748b" strokeWidth="1.4" />
        </>
      )}
      {/* findings → amber dot top-right */}
      {!st.isMissing && st.findingCount > 0 && (
        <circle cx={x + TW - 4} cy={y + 5} r="3.2" fill="#f59e0b" stroke="#fff" strokeWidth="0.8" />
      )}
      {/* FDI label */}
      <text
        x={x + (TW + 3) / 2 + 1.5}
        y={y + GLYPH_H + 10}
        textAnchor="middle"
        fontSize="8.5"
        fontWeight="600"
        fill="#475569"
        fontFamily="Inter, sans-serif"
      >
        {fdi}
      </text>
    </g>
  );
}

function LegendDot({ color, filled, label, cross }) {
  return (
    <span style={{ display: "inline-flex", alignItems: "center", gap: 4, fontSize: 9, color: "#475569", fontFamily: "Inter, sans-serif" }}>
      <svg width="14" height="14" viewBox="0 0 14 14" style={{ flexShrink: 0 }}>
        <rect x="2.5" y="1.5" width="9" height="11" rx="2.5" fill={filled || "#fff"} stroke={color} strokeWidth="1.3" />
        {cross && (
          <>
            <line x1="4" y1="3" x2="10" y2="11" stroke="#64748b" strokeWidth="1" />
            <line x1="10" y1="3" x2="4" y2="11" stroke="#64748b" strokeWidth="1" />
          </>
        )}
      </svg>
      {label}
    </span>
  );
}

export function FlatDentitionChart({ patientId, chart: chartProp }) {
  const [chart, setChart] = useState(chartProp ?? null);
  useEffect(() => {
    if (chartProp) return;
    setChart(loadChart(patientId));
  }, [patientId, chartProp]);

  const toothDiagnoses = chart?.toothDiagnoses ?? {};
  const findingsByTooth = chart?.findingsByTooth ?? {};

  // Nothing recorded → don't render the chart at all.
  const anyData =
    Object.values(toothDiagnoses).some((a) => (a || []).length > 0) ||
    Object.values(findingsByTooth).some((a) => (a || []).length > 0);
  if (!anyData) return null;

  const rowY = (rowIdx) => 6 + rowIdx * (GLYPH_H + LABEL_H + ROW_GAP);
  const svgH = rowY(2) - ROW_GAP + 4;

  return (
    <section
      style={{ marginTop: 10, breakInside: "avoid", WebkitPrintColorAdjust: "exact", printColorAdjust: "exact" }}
      data-dental-flat-chart="true"
    >
      <h3
        style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 12, fontWeight: 700, color: "#334155", margin: "0 0 6px", fontFamily: "Inter, sans-serif" }}
      >
        Dental Chart
        <span style={{ fontSize: 9, fontWeight: 500, color: "#94a3b8" }}>(upper &amp; lower)</span>
      </h3>
      <svg width="100%" viewBox={`0 0 ${CHART_W} ${svgH}`} style={{ maxWidth: CHART_W, overflow: "visible" }}>
        {/* upper / lower midline separators (vertical, between quadrants) */}
        <line x1={xFor(8) - CENTER_GAP / 2 - 2} y1={rowY(0) - 2} x2={xFor(8) - CENTER_GAP / 2 - 2} y2={rowY(0) + GLYPH_H + 2} stroke="#e2e8f0" strokeWidth="1" />
        <line x1={xFor(8) - CENTER_GAP / 2 - 2} y1={rowY(1) - 2} x2={xFor(8) - CENTER_GAP / 2 - 2} y2={rowY(1) + GLYPH_H + 2} stroke="#e2e8f0" strokeWidth="1" />
        {UPPER_ROW.map((fdi, i) => (
          <Tooth key={`u-${fdi}`} fdi={fdi} x={xFor(i)} y={rowY(0)} st={toothState(fdi, toothDiagnoses, findingsByTooth)} />
        ))}
        {LOWER_ROW.map((fdi, i) => (
          <Tooth key={`l-${fdi}`} fdi={fdi} x={xFor(i)} y={rowY(1)} st={toothState(fdi, toothDiagnoses, findingsByTooth)} />
        ))}
      </svg>
      <div style={{ display: "flex", gap: 14, marginTop: 4, flexWrap: "wrap" }}>
        <LegendDot color="#7c3aed" filled="#ede9fe" label="Treated / diagnosis" />
        <LegendDot color="#d97706" label="Finding" />
        <LegendDot color="#94a3b8" filled="#e2e8f0" cross label="Missing" />
      </div>
    </section>
  );
}
