"use client";

// DentitionSnapshot — displays the 3D front-view PNG that DentalCanvas captures
// from the live (correctly-sized) dentition canvas and stores in localStorage.
// Shows that image when available; otherwise falls back to the SVG chart so the
// report/exam always has a teeth diagram (and prints reliably).

import { useEffect, useMemo, useState } from "react";
import { FlatDentitionChart } from "./FlatDentitionChart";

const SNAPSHOT_PREFIX = "dental.exam.snapshot.";
const CHART_PREFIX = "dental.exam.chart.";
const SNAPSHOT_EVENT = "dental-snapshot-updated";

function resolvePid(patientId) {
  if (patientId) return patientId;
  if (typeof window !== "undefined") {
    try { return new URLSearchParams(window.location.search).get("patientId") || "apt-1"; } catch { return "apt-1"; }
  }
  return "apt-1";
}

export function DentitionSnapshot({ patientId, chart: chartProp, toothDiagnoses, findingsByTooth, implantTeeth, title = "Dental Chart" }) {
  const pid = resolvePid(patientId);
  const [img, setImg] = useState(null);
  useEffect(() => {
    const load = () => { try { setImg(window.localStorage.getItem(`${SNAPSHOT_PREFIX}${pid}`) || null); } catch { setImg(null); } };
    load();
    const onEvt = (e) => { if (!e?.detail?.patientId || e.detail.patientId === pid) load(); };
    window.addEventListener(SNAPSHOT_EVENT, onEvt);
    window.addEventListener("storage", load);
    return () => { window.removeEventListener(SNAPSHOT_EVENT, onEvt); window.removeEventListener("storage", load); };
  }, [pid]);

  // SVG fallback data (live props in the exam, or the saved chart elsewhere).
  const svgChart = useMemo(() => {
    if (toothDiagnoses) {
      return {
        toothDiagnoses: Object.fromEntries(Object.entries(toothDiagnoses).map(([f, s]) => [f, s instanceof Set ? [...s] : (s || [])])),
        findingsByTooth: findingsByTooth || {},
      };
    }
    if (chartProp) return chartProp;
    if (typeof window !== "undefined") {
      try { const raw = window.localStorage.getItem(`${CHART_PREFIX}${pid}`); return raw ? JSON.parse(raw) : null; } catch { return null; }
    }
    return null;
  }, [toothDiagnoses, findingsByTooth, chartProp, pid]);

  // Any data at all? (so we don't render an empty section)
  const hasData = useMemo(() => {
    if (img) return true;
    const c = svgChart;
    if (!c) return false;
    const td = c.toothDiagnoses || {};
    return Object.values(td).some((a) => (a || []).length > 0) || Object.values(c.findingsByTooth || {}).some((a) => (a || []).length > 0);
  }, [img, svgChart]);

  if (!hasData) return null;

  return (
    <section style={{ marginTop: 10, breakInside: "avoid", WebkitPrintColorAdjust: "exact", printColorAdjust: "exact" }} data-dentition-snapshot="true">
      {title ? (
        <h3 style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 12, fontWeight: 700, color: "#334155", margin: "0 0 6px", fontFamily: "Inter, sans-serif" }}>
          {title}
          <span style={{ fontSize: 9, fontWeight: 500, color: "#94a3b8" }}>(front view)</span>
        </h3>
      ) : null}
      {img ? (
        <div style={{ width: "100%", maxWidth: 460, height: 190, borderRadius: 10, overflow: "hidden", background: "linear-gradient(180deg,#f8fafc,#eef2f7)", border: "1px solid #e2e8f0" }}>
          <img src={img} alt="Dentition front view" style={{ width: "100%", height: "100%", objectFit: "contain" }} />
        </div>
      ) : (
        <FlatDentitionChart chart={svgChart} title={null} />
      )}
    </section>
  );
}
